class Repositionable{static start(t){const e="string"==typeof t?document.getElementById(t):t;if(!e)return;let n,o,s,l,c=!1;e.addEventListener("mousedown",t=>{c=!0;const i=e.getBoundingClientRect();n=t.clientX,o=t.clientY,s=i.left,l=i.top,t.preventDefault()}),document.addEventListener("mousemove",t=>{if(!c)return;const i=t.clientX-n,u=t.clientY-o;e.style.position="absolute",e.style.left=s+i+"px",e.style.top=l+u+"px",t.preventDefault()}),document.addEventListener("mouseup",()=>{c=!1}),e.addEventListener("touchstart",t=>{c=!0;const i=e.getBoundingClientRect();n=t.touches[0].clientX,o=t.touches[0].clientY,s=i.left,l=i.top,t.preventDefault()}),document.addEventListener("touchmove",t=>{if(!c)return;const i=t.touches[0].clientX-n,u=t.touches[0].clientY-o;e.style.position="absolute",e.style.left=s+i+"px",e.style.top=l+u+"px",t.preventDefault()}),document.addEventListener("touchend",()=>{c=!1})}}